def generate_permutation(n, k):
    if k == 0:
        return list(range(1, n+1))
    elif k == n-1:
        return list(reversed(range(1, n+1)))

    perm = [0] * n
    remaining = list(range(1, n+1))
    count = 0

    while count < k:
        max_val = max(remaining)
        pos = len(remaining) - 1
        while pos > 0 and remaining[pos-1] > max_val - 1:
            pos -= 1
        if pos == 0:
            perm[0] = remaining.pop()
            count += 1
        else:
            perm[pos] = remaining.pop(pos)
            count += 1

    perm.extend(remaining[::-1])
    return perm

