import sys

def generate_permutation(n, k):
    if k == 0:
        return list(range(1, n + 1))
    elif k == n - 1:
        return list(reversed(range(1, n + 1)))

    result = [0] * n
    remaining = list(range(1, n + 1))

    for i in range(n - 1):
        if k == 0:
            result[i] = remaining[0]
            remaining.pop(0)
        else:
            jump = min(k, len(remaining) - 1)
            result[i] = remaining[jump]
            remaining.pop(jump)
            k -= jump

    result[-1] = remaining[0]
    return result

