def find_permutation(n, k):
    if k == 0:
        return list(range(1, n + 1))
    elif k == n - 1:
        return list(reversed(range(1, n + 1)))

    perm = [0] * n
    remaining_numbers = list(range(1, n + 1))
    count = 0

    for i in range(n - 1):
        if count == k:
            break
        max_val = remaining_numbers[-1]
